static void disp_loop(char **map1, char **map2, int round, char **av)
{
    if (((round % 2) == 0 && av[2] != NULL) ||
        ((round % 2) != 0 && av[2] == NULL)) {
        mputstr("my positions:\n");
        display_map(map1);
        mputstr("enemy's positions:\n");
        display_map(map2);
    }
