static void fill_empty_map(char ***map_usr)
{
    char c = 'A';

    (*map_usr)[0][0] = 32;
    (*map_usr)[0][1] = '|';
    for (int a = 2; a != 17; a++) {
        (*map_usr)[0][a] = ((a % 2) == 0) ? c : 32;
        c += ((a % 2) == 0) ? 1 : 0;
    }
    for (int a = 0; a != 17; a++)
        (*map_usr)[1][a] = (a != 1) ? '-' : '+';
    for (int a = 2; a != 10; a++) {
        (*map_usr)[a][0] = a + 47;
        (*map_usr)[a][1] = '|';
        for (int b = 2; b != 17; b++) {
            if ((b % 2) == 0)
                (*map_usr)[a][b] = '.';
            else
                (*map_usr)[a][b] = ' ';
        }
    }
